#!/usr/bin/env node
'use strict';

/**
 * Generates database/seed.sql (reference data + realistic demo data).
 *   node database/tools/generate-seed.js
 *
 * Demo timestamps are written relative to UTC_TIMESTAMP() so the dashboard always shows
 * "today", "this month" and trends no matter when the file is imported.
 * Deterministic PRNG -> the generated file is stable between runs.
 */
const fs = require('node:fs');
const path = require('node:path');

// bcrypt hash of "Admin@1234" (cost 12). Change it after first login — the owner is forced to.
const DEFAULT_PASSWORD_HASH = '$2b$12$tdInEICNwYyiP0tCAHua7.BFJGJzClcRSdkcy1g2/xWCDrBeNh/JK';

let seed = 20261010;
const rand = () => {
  seed = (seed * 1664525 + 1013904223) % 4294967296;
  return seed / 4294967296;
};
const int = (a, b) => a + Math.floor(rand() * (b - a + 1));
const pick = (arr) => arr[Math.floor(rand() * arr.length)];
const weighted = (pairs) => {
  const total = pairs.reduce((s, [, w]) => s + w, 0);
  let r = rand() * total;
  for (const [v, w] of pairs) if ((r -= w) <= 0) return v;
  return pairs[0][0];
};
const q = (v) => {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return Number.isInteger(v) ? String(v) : v.toFixed(2);
  if (typeof v === 'object' && v.raw) return v.raw;
  return `'${String(v).replace(/\\/g, '\\\\').replace(/'/g, "''")}'`;
};
const raw = (s) => ({ raw: s });
const agoMin = (m) => raw(`UTC_TIMESTAMP() - INTERVAL ${m} MINUTE`);
const agoDate = (d) => raw(`DATE(UTC_TIMESTAMP() + INTERVAL 7 HOUR) - INTERVAL ${d} DAY`);
const r2 = (n) => Math.round(n * 100) / 100;

const out = [];
const insert = (table, cols, rows, chunk = 200) => {
  for (let i = 0; i < rows.length; i += chunk) {
    const values = rows.slice(i, i + chunk).map((r) => `(${r.map(q).join(', ')})`).join(',\n  ');
    out.push(`INSERT INTO ${table} (${cols.join(', ')}) VALUES\n  ${values};`);
  }
};

