// ---------------------------------------------------------------- sales (90 days)
out.push('\n-- Demo: 180 days of sales across channels');
const channelWeights = [['pos', 30], ['shopee', 28], ['tiktok', 24], ['facebook', 8], ['line', 6], ['instagram', 4]];
const feeRate = { shopee: 0.09, tiktok: 0.08 };
const orders = [];
const orderMeta = []; // for the demo ledger: day bucket, payment method, money
const items = [];
const payments = [];
let orderId = 0;
let itemId = 0;
for (let d = 179; d >= 0; d -= 1) {
  const growth = 0.6 + (179 - d) / 180;
  const weekend = [0, 6].includes(new Date(Date.now() - d * 86400000).getDay()) ? 1.3 : 1;
  const count = d === 0 ? int(6, 10) : Math.round(int(5, 10) * growth * weekend);
  for (let k = 0; k < count; k += 1) {
    orderId += 1;
    const channel = weighted(channelWeights);
    // today's orders land within the last few hours so they count as "today" in Bangkok time
    const minutesAgo = d === 0 ? int(5, 300) : d * 1440 + int(-300, 600);
    let subtotal = 0;
    let costTotal = 0;
    const lines = int(1, 3);
    for (let l = 0; l < lines; l += 1) {
      const pi = channel === 'tiktok' && rand() < 0.5 ? pick([0, 4, 7, 9]) : int(0, products.length - 1);
      const p = products[pi];
      const qty = rand() < 0.8 ? 1 : int(2, 3);
      itemId += 1;
      const lineTotal = p[3] * qty;
      subtotal += lineTotal;
      costTotal += p[4] * qty;
      items.push([itemId, orderId, pi + 1, p[1], qty, p[3], p[4], 0, lineTotal]);
    }
    const discount = rand() < 0.2 ? r2(subtotal * 0.1) : 0;
    const shipping = channel === 'pos' || subtotal >= 500 ? 0 : 40;
    const total = r2(subtotal - discount + shipping);
    const vat = r2((total * 7) / 107);
    const platformFee = r2(total * (feeRate[channel] || 0));
    const status = d === 0 ? pick(['paid', 'paid', 'packed']) : rand() < 0.04 ? 'cancelled' : rand() < 0.02 ? 'refunded' : 'completed';
    orders.push([orderId, 1, channel === 'pos' ? int(1, 2) : 1, rand() < 0.4 ? int(1, 15) : null,
      `SO${String(orderId).padStart(6, '0')}`, channel, status, subtotal, discount, shipping, vat, total, costTotal, platformFee, agoMin(minutesAgo)]);
    const method = channel === 'pos' ? pick(['cash', 'promptpay', 'card']) : 'platform';
    payments.push([1, orderId, method, total, agoMin(minutesAgo)]);
    if (!['cancelled', 'refunded'].includes(status)) {
      orderMeta.push({ day: Math.max(Math.round(minutesAgo / 1440), 0), method, total, vat, cost: costTotal, fee: platformFee });
    }
  }
}
insert('sales_orders', ['id', 'org_id', 'branch_id', 'customer_id', 'order_no', 'channel', 'status', 'subtotal', 'discount', 'shipping_fee', 'vat_amount', 'total', 'cost_total', 'platform_fee', 'ordered_at'], orders);
insert('sales_order_items', ['id', 'order_id', 'product_id', 'name', 'quantity', 'unit_price', 'unit_cost', 'discount', 'line_total'], items, 400);
insert('payments', ['org_id', 'order_id', 'method', 'amount', 'paid_at'], payments, 400);

